DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_completed INT;
  cur_attempted INT;
BEGIN
  FOR rec IN SELECT * FROM shift_events ORDER BY event_id LOOP
    SELECT shift_status, trips_completed, trips_attempted INTO cur_status, cur_completed, cur_attempted
    FROM driver_shifts WHERE driver_id = rec.driver_id;

    IF rec.event_type = 1 AND cur_status = 'off' THEN
      UPDATE driver_shifts
      SET shift_status = 'active', trips_completed = 0, trips_attempted = 0
      WHERE driver_id = rec.driver_id;
    ELSIF rec.event_type = 2 AND cur_status = 'active' THEN
      IF rec.trip_successful THEN
        UPDATE driver_shifts
        SET trips_attempted = trips_attempted + 1, trips_completed = trips_completed + 1
        WHERE driver_id = rec.driver_id;
      ELSE
        UPDATE driver_shifts
        SET trips_attempted = trips_attempted + 1
        WHERE driver_id = rec.driver_id;
      END IF;
    ELSIF rec.event_type = 3 AND cur_status = 'active' AND cur_attempted > 0 THEN
      UPDATE driver_shifts
      SET shift_status = 'off'
      WHERE driver_id = rec.driver_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM driver_shifts ORDER BY driver_id;
